parameters.jsCode:
const reply = $input.first().json;
if (reply.error?.message) throw new Error('MartLLM could not write the plan: ' + reply.error.message);
const text = reply.choices?.[0]?.message?.content || '';
const found = text.match(/\{[\s\S]*\}/);
let plan;
try { plan = JSON.parse(found ? found[0] : text); } catch (e) {
  throw new Error('The writing model did not answer in the expected shape. Run the workflow again, or pick another script_model in Settings.');
}
const s = $('Settings').first().json;
const scenes = (plan.scenes || []).filter((x) => x && x.video_prompt).slice(0, Number(s.max_scenes) || 6);
if (!scenes.length) throw new Error('The writing model found no scenes in the script. Check the script in Settings and run again.');
// One item per scene, with the request both the price check and the start send.
return scenes.map((x, i) => ({ json: {
  scene: i + 1,
  title: String(plan.title || 'Storyboard'),
  text: String(x.text || ''),
  request: {
    model: s.video_model,
    prompt: x.video_prompt + ' Look: ' + s.look + '.',
    duration_seconds: s.seconds_per_scene,
    resolution: s.resolution,
    aspect_ratio: s.shape,
    audio: s.sound,
  },
} }));

// Adds up the price of every clip before any starts. Above max_total_usd, or a request MartLLM refuses: stop here, nothing is charged.
const scenes = $('Split the scenes').all().map((i) => i.json);
const quotes = $input.all().map((i) => i.json);
const limit = Number($('Settings').first().json.max_total_usd);
const usd = (x) => '$' + Number(x).toFixed(2);
const tidy = (m) => String(m).replace(/[.\s]+$/, '');
const rows = scenes.map((sc, i) => {
  const q = quotes[i] || {};
  if (q.error?.message) throw new Error('MartLLM could not price scene ' + sc.scene + ': ' + tidy(q.error.message) + '. Nothing was made and nothing was charged.');
  if (q.valid !== true) throw new Error('MartLLM could not price scene ' + sc.scene + '. Nothing was made and nothing was charged.');
  return { ...sc, price_usd: q.cost_usd, most_usd: q.max_cost_usd };
});
const most = rows.reduce((sum, r) => sum + r.most_usd, 0);
if (most > limit) {
  throw new Error(rows.length + ' clips can cost up to ' + usd(most) + ' (' + rows.map((r) => 'scene ' + r.scene + ' ' + usd(r.most_usd)).join(', ') + '), more than max_total_usd in Settings (' + usd(limit) + '). Nothing was made and nothing was charged. Raise the limit, or lower max_scenes, seconds_per_scene or resolution.');
}
// Each clip may use its price plus an equal share of what is left under the limit, so the whole run never passes max_total_usd.
const spare = (limit - most) / rows.length;
return rows.map((r) => ({ json: { ...r, cap_usd: Math.floor((r.most_usd + spare) * 10000) / 10000 } }));

