parameters.jsCode:
// Keeps the jobs that started. A scene MartLLM refused is listed at the end with MartLLM's own message.
const replies = $input.all().map((i) => i.json);
const started = replies.filter((r) => r.id);
const tidy = (m) => String(m).replace(/[.\s]+$/, '');
if (!started.length) {
  throw new Error('No clip could start: ' + tidy(replies[0]?.error?.message || 'MartLLM did not accept the request') + '. Nothing was charged.');
}
return started.map((r) => ({ json: r }));

// Looks at every job together. While any is still being made, all go round the loop again.
// After 45 checks (15 minutes) it stops waiting; those jobs still finish and show in your MartLLM dashboard.
const jobs = $input.all().map((i) => i.json);
const busy = jobs.some((j) => ['queued', 'running'].includes(j.status));
const waiting = busy && $runIndex < 45;
return jobs.map((j) => ({ json: { ...j, waiting } }));

// Passes on the clips that were made. If none was, stop with MartLLM's own reasons.
const jobs = $input.all().map((i) => i.json);
const made = jobs.filter((j) => j.status === 'succeeded' && j.results?.[0]?.url);
if (!made.length) {
  throw new Error('No clip was made. ' + jobs.map((j) => 'Scene ' + j.metadata?.scene + ': ' + (j.error?.message ? String(j.error.message).replace(/[.\s]+$/, '') : (['queued', 'running'].includes(j.status) ? 'still being made after 15 minutes; it will show in your MartLLM dashboard' : 'it ended as ' + j.status))).join('. ') + '. Nothing was charged.');
}
return made.map((j) => ({ json: j }));

// One row per scene, in order: the script text, the clip link, what it cost, and the file itself.
// A scene that was not made stays in the list with the reason.
const scenes = $('Check the total').all().map((i) => i.json);
const starts = $('Start each clip').all().map((i) => i.json);
const jobs = $('Any still being made?').all().map((i) => i.json);
const made = $('Sort the results').all().map((i) => i.json);
const files = {};
$input.all().forEach((item, i) => { if (item.binary?.clip) files[made[i].id] = item.binary.clip; });
return scenes.map((sc, i) => {
  const job = jobs.find((j) => j.metadata?.scene === String(sc.scene));
  const row = { scene: sc.scene, storyboard: sc.title, text: sc.text, video_prompt: sc.request.prompt, seconds: sc.request.duration_seconds };
  if (!job) return { json: { ...row, made: false, why: starts.find((r) => r.metadata?.scene === String(sc.scene))?.error?.message || starts[i]?.error?.message || 'MartLLM did not accept the request', cost_usd: 0 } };
  if (job.status !== 'succeeded') return { json: { ...row, made: false, why: (job.error?.message ? String(job.error.message).replace(/[.\s]+$/, '') : (['queued', 'running'].includes(job.status) ? 'still being made after 15 minutes; it will show in your MartLLM dashboard' : 'it ended as ' + job.status)), cost_usd: 0 } };
  const out = { json: { ...row, made: true, clip_link: job.results[0].url, link_note: 'Needs your MartLLM key and is kept about 3 hours. The file is attached to this row.',
    cost_usd: job.usage?.cost_usd ?? job.estimated_cost_usd, cost_is_final: job.usage?.cost_usd != null, model: job.model } };
  if (files[job.id]) out.binary = { clip: { ...files[job.id], fileName: 'scene-' + String(sc.scene).padStart(2, '0') + '.mp4' } };
  return out;
});
